"""Two-panel, resumable human review; image-bound labels, no automatic approvals."""
from pathlib import Path
import json


def publish(folder,rows,progress):
    folder=Path(folder);payload=[]
    for row in rows:
        a,b=Path(row['positive_images'][0]),Path(row['engine_image'])
        if row['display_swapped']:a,b=b,a
        payload.append(dict(pair_id=row['pair_id'],a=str(a.relative_to(folder)),b=str(b.relative_to(folder)),
            swapped=row['display_swapped'],review_hash=row['review_hash'],category=row['category'],format=row['format'],
            source=row['source_image'],repeat=bool(row.get('reliability_repeat_of')),diagnostic=row['status']=='review_only_constraint_failure'))
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MagiCanvas preference campaign</title><style>body{font:17px system-ui;background:#101820;color:#edf2f7;margin:20px}header{max-width:1200px}a{color:#9ed4ff}#pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0}img{width:100%;height:66vh;object-fit:contain;background:#15212c}button,select{padding:10px;margin:5px;font-size:16px}button{cursor:pointer}#status{min-height:2em}#comment{width:min(90vw,750px)}@media(max-width:750px){#pair{grid-template-columns:1fr}img{height:45vh}}</style><header><h1>Layout preference campaign</h1><p>Choose the stronger layout based on readability, alignment, spacing, grouping, subject visibility and use of space. Both panels are actual engine-generated arrangements with Qwen enabled. Neither side is automatically correct; A/B order is randomized. <b>Neither is good</b> is different from an acceptable tie. Occasional repeats check consistency and are excluded from training.</p><p id="progress">__PROGRESS__</p><p><a href="../regression_suite/index.html">Unified regression viewer</a> · <a id="source" target="_blank">Open original design</a></p><label>Category <select id="category"><option value="">All</option><option value="new-level3">New Level 3-style designs</option><option value="dataset">Dataset families</option></select></label><label>Format <select id="format"><option value="">All</option>__FORMATS__</select></label><button id="unreviewed">Next unreviewed</button><p id="status"></p></header><div id="pair"><figure><figcaption>A</figcaption><a id="zoom-a" target="_blank"><img id="a" alt="Layout A"></a></figure><figure><figcaption>B</figcaption><a id="zoom-b" target="_blank"><img id="b" alt="Layout B"></a></figure></div><p><button id="aWins">1 · Prefer A</button><button id="bWins">2 · Prefer B</button><button id="tie">3 · Acceptable tie</button><button id="neither">4 · Neither is good</button><button id="prev">Previous</button><button id="next">Next</button><button id="export">Export labels</button></p><label>Optional reason <input id="comment" placeholder="e.g. better grouping; both too small; unreadable text"></label><script>const rows=__ROWS__,key='magicanvas-preference-campaign-v3';let labels=JSON.parse(localStorage.getItem(key)||'{}'),i=0,filtered=[];function filter(){filtered=rows.filter(r=>(!category.value||r.category===category.value)&&(!format.value||r.format===format.value));i=0;show()}const category=document.getElementById('category'),format=document.getElementById('format');function show(){let r=filtered[i];if(!r){document.getElementById('status').textContent='No comparisons in this filter yet. Reload after more generation finishes.';return}for(const side of ['a','b']){document.getElementById(side).src=r[side];document.getElementById('zoom-'+side).href=r[side]}document.getElementById('source').href=r.source;document.getElementById('comment').value=labels[r.pair_id]?.comment||'';let count=rows.filter(r=>labels[r.pair_id]?.review_hash===r.review_hash).length;document.getElementById('status').textContent=`${i+1}/${filtered.length} in filter · ${count}/${rows.length} reviewed · ${r.category} / ${r.format} · choice: ${labels[r.pair_id]?.display_choice||'unreviewed'}`;}function nextBlank(){for(let n=1;n<=filtered.length;n++){let j=(i+n)%filtered.length,r=filtered[j];if(labels[r.pair_id]?.review_hash!==r.review_hash){i=j;show();return}}show()}function vote(choice){let r=filtered[i];if(!r)return;let decision=(choice==='tie'||choice==='neither')?'skip':((choice==='a')!==r.swapped?'accept':'prefer_candidate');labels[r.pair_id]={pair_id:r.pair_id,decision,display_choice:choice,reject_both:choice==='neither',review_hash:r.review_hash,comment:document.getElementById('comment').value.trim(),reviewed_at:new Date().toISOString()};localStorage.setItem(key,JSON.stringify(labels));nextBlank()}document.getElementById('aWins').onclick=()=>vote('a');document.getElementById('bWins').onclick=()=>vote('b');document.getElementById('tie').onclick=()=>vote('tie');document.getElementById('neither').onclick=()=>vote('neither');document.getElementById('prev').onclick=()=>{i=Math.max(0,i-1);show()};document.getElementById('next').onclick=()=>{i=Math.min(filtered.length-1,i+1);show()};document.getElementById('unreviewed').onclick=nextBlank;category.onchange=format.onchange=filter;document.getElementById('export').onclick=()=>{const valid=Object.values(labels).filter(x=>rows.some(r=>r.pair_id===x.pair_id&&r.review_hash===x.review_hash));const blob=new Blob([valid.map(x=>JSON.stringify(x)).join('\\n')+'\\n'],{type:'application/x-ndjson'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='siglip-campaign-preferences-v3.jsonl';a.click();URL.revokeObjectURL(a.href)};document.addEventListener('keydown',e=>{if(e.target.tagName==='INPUT'||e.target.tagName==='SELECT')return;const choice={'1':'a','2':'b','3':'tie','4':'neither'}[e.key];if(choice)vote(choice)});filter();</script></html>'''
    opts=''.join(f'<option value="{s}">{s}</option>' for s in sorted({r['format'] for r in rows}))
    text=json.dumps(payload).replace('</','<\\/')
    page=page.replace('__ROWS__',text).replace('__FORMATS__',opts).replace('__PROGRESS__',progress)
    page=page.replace("${r.category} / ${r.format} · choice:","${r.category} / ${r.format}${r.diagnostic?' · DIAGNOSTIC ONLY (neither layout passes all constraints)':''} · choice:")
    temp=folder/'review.html.next';temp.write_text(page);temp.replace(folder/'review.html')
